import type { WfrpActor, WfrpMutationItem } from "../../../../types/foundry";
import type { MutationGrantDefinition } from "../../../../types/mutants-handbook";
import { MODULE_ID } from "../../../constants";
import {
  configureGrantData,
  getGrantOwnership,
  mutationGrantSignature,
  type MutationSkillGrantLedger,
  type MutationSkillGrantOwner,
} from "./grant-data";
import {
  actorItems,
  baseAdvances,
  canonicalPriority,
  clearLedgerChanges,
  isAutomationManaged,
  isItem,
  rankedSignatureData,
  setAdvances,
  setLedgerFlag,
  updateItem,
} from "./ranked-skill-items";

export interface RankedSkillGrantRequest {
  grant: MutationGrantDefinition;
  mutation: WfrpMutationItem;
}

interface RankedSkillContribution extends MutationSkillGrantOwner {
  grant: MutationGrantDefinition;
  mutationName: string;
  name: string;
}

async function desiredContributions(
  actor: WfrpActor,
  requests: RankedSkillGrantRequest[],
): Promise<RankedSkillContribution[]> {
  const sourceNames = new Map<string, string>();
  await Promise.all(
    requests.map(async ({ grant, mutation }) => {
      if (grant.configure?.name || sourceNames.has(grant.sourceUuid)) return;
      const signature = mutationGrantSignature(grant);
      const owned = actorItems(actor).find(
        (item) =>
          item.type === "skill" &&
          rankedSignatureData(item)?.owners.some(
            (owner) =>
              owner.sourceUuid === grant.sourceUuid &&
              ((owner.ownerId === mutation.id && owner.grantKey === grant.key) ||
                owner.signature === signature),
          ),
      );
      if (owned) {
        sourceNames.set(grant.sourceUuid, owned.name);
        return;
      }
      const source = await fromUuid(grant.sourceUuid);
      if (isItem(source)) sourceNames.set(grant.sourceUuid, source.name);
    }),
  );

  return requests.map(({ grant, mutation }) => ({
    grant,
    grantKey: grant.key,
    mutationName: mutation.name,
    name: grant.configure?.name ?? sourceNames.get(grant.sourceUuid) ?? grant.name,
    ownerId: mutation.id,
    ranks: grant.ranks ?? 1,
    signature: mutationGrantSignature(grant),
    sourceUuid: grant.sourceUuid,
  }));
}

function contributionOwners(contributions: RankedSkillContribution[]): MutationSkillGrantOwner[] {
  return contributions.map(({ grantKey, ownerId, ranks, signature, sourceUuid }) => ({
    grantKey,
    ownerId,
    ranks,
    signature,
    sourceUuid,
  }));
}

async function createRankedSkill(
  actor: WfrpActor,
  contributions: RankedSkillContribution[],
): Promise<void> {
  const first = contributions[0];
  if (!first) return;
  const source = await fromUuid(first.sourceUuid);
  if (!isItem(source)) {
    ui.notifications.warn(
      `${first.mutationName}: could not grant ${first.name}. Enable its source module and reconcile mutation automation.`,
    );
    return;
  }

  const data = configureGrantData(source.toObject(), first.grant);
  delete data["_id"];
  delete data["_key"];
  // A positive-advance Skill is merged by WFRP before Foundry creates it, losing this module's
  // ledger flags. Create a zero-advance shell and apply the contribution in a normal update.
  setAdvances(data, 0);
  setLedgerFlag(data, {
    appliedRanks: 0,
    managed: true,
    owners: [],
    version: 1,
  });
  const created = await actor.createEmbeddedDocuments("Item", [data], {
    skipExperienceChecks: true,
    skipSpecialisationChoice: true,
  });
  const createdItem = created.find(isItem);
  if (
    !createdItem &&
    !actorItems(actor).some((item) => item.type === "skill" && item.name === first.name)
  ) {
    throw new Error(`${first.mutationName}: Foundry prevented the ${first.name} Skill grant.`);
  }

  // Re-read the actor collection: another client may have created the same Skill while the
  // shell was being added. Group reconciliation deterministically adopts one and converges any
  // zero-base automation duplicates without ever relying on WFRP's merge result.
  await reconcileRankedSkillGroup(actor, first.name, contributions, false);
}

async function clearRankedSkillGroup(
  actor: WfrpActor,
  candidates: WfrpMutationItem[],
): Promise<void> {
  const deleteIds: string[] = [];
  for (const item of candidates) {
    const ranked = rankedSignatureData(item);
    if (!ranked) continue;
    const base = baseAdvances(item);
    if (ranked.managed && base === 0 && !getGrantOwnership(item)) deleteIds.push(item.id);
    else await updateItem(actor, item, clearLedgerChanges(base));
  }
  if (deleteIds.length > 0) await actor.deleteEmbeddedDocuments("Item", deleteIds);
}

async function reconcileRankedSkillGroup(
  actor: WfrpActor,
  name: string,
  contributions: RankedSkillContribution[],
  allowCreate = true,
): Promise<void> {
  const candidates = actorItems(actor)
    .filter((item) => item.type === "skill" && item.name === name)
    .sort(
      (left, right) =>
        canonicalPriority(left) - canonicalPriority(right) || left.id.localeCompare(right.id),
    );

  if (contributions.length === 0) {
    await clearRankedSkillGroup(actor, candidates);
    return;
  }
  const canonical = candidates[0];
  if (!canonical) {
    if (!allowCreate) {
      throw new Error(`${name}: Foundry did not retain the mutation Skill grant.`);
    }
    await createRankedSkill(actor, contributions);
    return;
  }

  const automatedExtras = candidates.slice(1).filter((item) => rankedSignatureData(item));
  const userDuplicates = candidates.slice(1).filter((item) => !rankedSignatureData(item));
  if (userDuplicates.length > 0) {
    ui.notifications.warn(
      `${name}: multiple user-owned Skills share this name. Mutation advances were applied only to ${canonical.name}; review the duplicates manually.`,
    );
  }

  const total = contributions.reduce((sum, contribution) => sum + contribution.ranks, 0);
  const base = baseAdvances(canonical, total);
  const current = rankedSignatureData(canonical);
  const ledger: MutationSkillGrantLedger = {
    appliedRanks: total,
    managed: current?.managed ?? getGrantOwnership(canonical)?.managed ?? false,
    owners: contributionOwners(contributions),
    version: 1,
  };
  await updateItem(actor, canonical, {
    "system.advances.value": base + total,
    [`flags.${MODULE_ID}.mutationSkillGrant`]: ledger,
  });

  const deleteIds: string[] = [];
  for (const extra of automatedExtras) {
    const extraBase = baseAdvances(extra);
    if (isAutomationManaged(extra) && extraBase === 0 && !getGrantOwnership(extra)) {
      deleteIds.push(extra.id);
    } else {
      await updateItem(actor, extra, clearLedgerChanges(extraBase));
      if (extraBase > 0) {
        ui.notifications.warn(
          `${name}: retained a duplicate Skill containing non-mutation advances; review the duplicate manually.`,
        );
      }
    }
  }
  if (deleteIds.length > 0) await actor.deleteEmbeddedDocuments("Item", deleteIds);
}

export async function reconcileRankedSkillGrants(
  actor: WfrpActor,
  requests: RankedSkillGrantRequest[],
): Promise<void> {
  const desired = await desiredContributions(actor, requests);
  const names = new Set(desired.map(({ name }) => name));
  for (const item of actorItems(actor)) {
    if (item.type === "skill" && rankedSignatureData(item)) names.add(item.name);
  }

  for (const name of [...names].sort()) {
    const contributions = desired
      .filter((contribution) => contribution.name === name)
      .sort(
        (left, right) =>
          left.ownerId.localeCompare(right.ownerId) || left.grantKey.localeCompare(right.grantKey),
      );
    await reconcileRankedSkillGroup(actor, name, contributions);
  }
}
