import type { FoundryDialogButton, WfrpActor, WfrpTest } from "../../../types/foundry";
import { formatMutationMessage, postMutationMessage, warnAboutMutation } from "./messages";
import { updateActor } from "./updates";

type TestChoice = "accept" | "dark-deal" | "fortune-reroll" | "fortune-sl";

function localize(key: string): string {
  if (!game) {
    throw new Error("Foundry game global is unavailable while resolving a corruption test.");
  }

  return game.i18n.localize(`FVTT_WFRP_RATTER.Mutations.${key}`);
}

function availableButtons(actor: WfrpActor, test: WfrpTest): FoundryDialogButton[] {
  const buttons: FoundryDialogButton[] = [];
  const fortune = Number(actor.system.status.fortune?.value ?? 0);

  if (test.failed && fortune > 0 && !test.context.fortuneUsedReroll) {
    buttons.push({ action: "fortune-reroll", label: localize("FortuneReroll") });
  }

  if (fortune > 0 && !test.context.fortuneUsedAddSL) {
    buttons.push({ action: "fortune-sl", label: localize("FortuneSL") });
  }

  buttons.push({ action: "dark-deal", label: localize("DarkDeal") });
  buttons.push({
    action: "accept",
    default: true,
    label: localize(test.failed ? "AcceptFailure" : "AcceptSuccess"),
  });
  return buttons;
}

async function chooseTestAction(actor: WfrpActor, test: WfrpTest): Promise<TestChoice> {
  if (!game) {
    throw new Error("Foundry game global is unavailable while resolving a corruption test.");
  }

  const choice = await foundry.applications.api.DialogV2.wait({
    buttons: availableButtons(actor, test),
    content: game.i18n.format(
      `FVTT_WFRP_RATTER.Mutations.${test.failed ? "TestResourcesPrompt" : "TestResourcesSuccessPrompt"}`,
      { name: actor.name },
    ),
    rejectClose: false,
    window: { title: localize("TestResourcesTitle") },
  });

  if (choice === "dark-deal" || choice === "fortune-reroll" || choice === "fortune-sl") {
    return choice;
  }

  return "accept";
}

async function rollWithResourceRollback(
  actor: WfrpActor,
  rollbackChanges: Record<string, unknown>,
  roll: () => Promise<void>,
  resource: string,
): Promise<void> {
  try {
    await roll();
  } catch (rollError) {
    try {
      await updateActor(actor, rollbackChanges);
    } catch (rollbackError) {
      throw new AggregateError(
        [rollError, rollbackError],
        `${resource} was spent, the reroll failed, and Foundry could not restore the resource.`,
        { cause: rollbackError },
      );
    }

    throw rollError;
  }
}

async function spendFortune(actor: WfrpActor, test: WfrpTest, addSL: boolean): Promise<boolean> {
  const current = Math.trunc(Number(actor.system.status.fortune?.value ?? 0));

  if (current <= 0) {
    warnAboutMutation(formatMutationMessage("FortuneUnavailable", { name: actor.name }));
    return false;
  }

  const remaining = current - 1;

  await updateActor(actor, { "system.status.fortune.value": remaining });

  if (addSL) {
    test.context.fortuneUsedAddSL = true;
    test.context.previousResult = { ...test.result };
    test.preData.SL = Math.trunc(test.result.SL) + 1;
    test.preData.slBonus = 0;
    test.preData.successBonus = 0;
    test.preData.roll = Math.trunc(test.result.roll);
    await rollWithResourceRollback(
      actor,
      { "system.status.fortune.value": current },
      () => test.roll(),
      "Fortune",
    );
  } else {
    test.context.fortuneUsedReroll = true;
    test.context.fortuneUsedAddSL = true;
    await rollWithResourceRollback(
      actor,
      { "system.status.fortune.value": current },
      () => test.reroll(),
      "Fortune",
    );
  }

  await postMutationMessage(
    formatMutationMessage(addSL ? "FortuneSLUsed" : "FortuneRerollUsed", {
      name: actor.name,
      remaining,
    }),
  );
  return true;
}

async function takeDarkDeal(actor: WfrpActor, test: WfrpTest): Promise<void> {
  const previousCorruption = Math.trunc(Number(actor.system.status.corruption.value));
  const corruption = previousCorruption + 1;

  await updateActor(actor, { "system.status.corruption.value": corruption });
  await rollWithResourceRollback(
    actor,
    { "system.status.corruption.value": previousCorruption },
    () => test.reroll(),
    "Dark Deal Corruption",
  );
  await postMutationMessage(
    formatMutationMessage("DarkDealUsed", {
      corruption,
      maximum: Number(actor.system.status.corruption.max),
      name: actor.name,
    }),
  );
}

export async function finalizeCorruptionTest(actor: WfrpActor, test: WfrpTest): Promise<boolean> {
  while (true) {
    const choice = await chooseTestAction(actor, test);

    if (choice === "accept") {
      return !test.failed;
    }

    if (choice === "dark-deal") {
      await takeDarkDeal(actor, test);
    } else {
      await spendFortune(actor, test, choice === "fortune-sl");
    }
  }
}
