import type { WfrpMutationItem } from "../../../../types/foundry";
import { MODULE_ID } from "../../../constants";
import { reportMutationError } from "../messages";
import { reconcileMutationAutomation, removeMutationGrantOwner } from "./grant-reconciliation";

function automatedOwnedMutation(value: unknown): WfrpMutationItem | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const item = value as Partial<WfrpMutationItem>;
  if (
    item.type !== "mutation" ||
    typeof item.id !== "string" ||
    typeof item.actor?.uuid !== "string"
  ) {
    return undefined;
  }
  const automation = item.flags?.[MODULE_ID]?.["mutationAutomation"];
  return typeof automation === "object" && automation !== null
    ? (item as WfrpMutationItem)
    : undefined;
}

function mutationSupportingItem(value: unknown): WfrpMutationItem | undefined {
  if (typeof value !== "object" || value === null) return undefined;
  const item = value as Partial<WfrpMutationItem>;
  if (typeof item.id !== "string" || typeof item.actor?.uuid !== "string") return undefined;
  const flags = item.flags?.[MODULE_ID];
  return typeof flags?.["mutationGrant"] === "object" ||
    typeof flags?.["mutationSkillGrant"] === "object"
    ? (item as WfrpMutationItem)
    : undefined;
}

function reportRejected(operation: Promise<void>): void {
  void operation.catch(reportMutationError);
}

export function isMutationAutomationHookAuthority(userId: unknown): boolean {
  return typeof userId === "string" && game?.user.id === userId;
}

export function registerMutationAutomationHooks(): void {
  Hooks.on("createItem", (document, _options, userId) => {
    if (!isMutationAutomationHookAuthority(userId)) return;
    const mutation = automatedOwnedMutation(document);
    if (mutation?.actor) {
      reportRejected(reconcileMutationAutomation(mutation.actor.uuid));
    }
  });

  Hooks.on("deleteItem", (document, _options, userId) => {
    if (!isMutationAutomationHookAuthority(userId)) return;
    const mutation = automatedOwnedMutation(document);
    if (mutation?.actor) {
      reportRejected(removeMutationGrantOwner(mutation.actor.uuid, mutation.id));
      return;
    }
    const supportingItem = mutationSupportingItem(document);
    if (supportingItem?.actor) {
      reportRejected(reconcileMutationAutomation(supportingItem.actor.uuid));
    }
  });
}
