import { getSeverityModifier } from "../../../functions/mutants-handbook/rules";
import type {
  ChaosPatron,
  HandbookSpecies,
  MutationNature,
  MutationSeverity,
} from "../../../types/mutants-handbook";
import type { FoundryRollTable, FoundryTableResult } from "../../../types/foundry";
import {
  MUTATION_TABLE_IDS,
  PATRON_TABLE_IDS,
  RATTER_TABLE_PACK,
  SEVERITY_TABLE_ID,
  SPECIES_TABLE_IDS,
} from "./constants";

function isRollTable(document: unknown): document is FoundryRollTable {
  return typeof document === "object" && document !== null && "draw" in document;
}

async function getTable(tableId: string): Promise<FoundryRollTable> {
  const pack = game?.packs.get(RATTER_TABLE_PACK);

  if (!pack) {
    throw new Error(`The required compendium ${RATTER_TABLE_PACK} is unavailable.`);
  }

  const table = await pack.getDocument(tableId);

  if (!isRollTable(table)) {
    throw new Error(`The required Mutant's Handbook table ${tableId} is unavailable.`);
  }

  return table;
}

async function drawTable(tableId: string, rollFormula?: string): Promise<FoundryTableResult> {
  const table = await getTable(tableId);
  const draw = await table.draw({
    displayChat: true,
    messageMode: "gm",
    recursive: true,
    ...(rollFormula ? { roll: new Roll(rollFormula) } : {}),
  });
  const result = draw.results[0];

  if (!result) {
    throw new Error(`The Mutant's Handbook table ${tableId} returned no result.`);
  }

  return result;
}

export function drawMutationNature(species: HandbookSpecies): Promise<FoundryTableResult> {
  return drawTable(SPECIES_TABLE_IDS[species]);
}

export function drawMutationSeverity(mutationCount: number): Promise<FoundryTableResult> {
  const modifier = getSeverityModifier(mutationCount);
  const formula = modifier > 0 ? `1d100 + ${modifier}` : "1d100";
  return drawTable(SEVERITY_TABLE_ID, formula);
}

export function drawMutation(
  nature: MutationNature,
  severity: Exclude<MutationSeverity, "chosen">,
): Promise<FoundryTableResult> {
  return drawTable(MUTATION_TABLE_IDS[severity][nature]);
}

export function drawPatronMutation(patron: ChaosPatron): Promise<FoundryTableResult> {
  return drawTable(PATRON_TABLE_IDS[patron]);
}
