import {
  countMutationNatures,
  resolveMutationNature,
} from "../../../functions/mutants-handbook/rules";
import type {
  ChaosPatron,
  ChosenPatron,
  MutationCounts,
  MutationNature,
} from "../../../types/mutants-handbook";
import type { MutationAcquisitionRule } from "../../../functions/mutants-handbook/automation/types";
import type { FoundryTableResult, WfrpActor, WfrpMutationItem } from "../../../types/foundry";
import { MODULE_ID } from "../../constants";
import { CHAOS_SPAWN_FLAG, CHOSEN_PATRON_FLAG, POSSESSION_REMOVED_FLAG } from "./constants";

const CHAOS_PATRONS: ChosenPatron[] = ["khorne", "nurgle", "slaanesh", "tzeentch", "unassigned"];

export interface ResolvedMutation {
  acquisition?: MutationAcquisitionRule;
  data: Record<string, unknown>;
  name: string;
  nature: MutationNature;
}

interface MutationAutomationFlag {
  acquisition?: MutationAcquisitionRule;
}

export function isWfrpActor(document: unknown): document is WfrpActor {
  if (typeof document !== "object" || document === null) {
    return false;
  }

  const actor = document as Partial<WfrpActor>;
  return (
    actor.type === "character" &&
    typeof actor.name === "string" &&
    typeof actor.uuid === "string" &&
    typeof actor.createEmbeddedDocuments === "function" &&
    typeof actor.deleteEmbeddedDocuments === "function" &&
    typeof actor.getFlag === "function" &&
    typeof actor.has === "function" &&
    typeof actor.setupCharacteristic === "function" &&
    typeof actor.setupSkill === "function" &&
    typeof actor.update === "function" &&
    typeof actor.updateEmbeddedDocuments === "function"
  );
}

function isMutationItem(document: unknown): document is WfrpMutationItem {
  if (typeof document !== "object" || document === null) {
    return false;
  }

  const item = document as Partial<WfrpMutationItem>;
  return (
    item.type === "mutation" &&
    typeof item.name === "string" &&
    typeof item.toObject === "function" &&
    !!item.system
  );
}

function copyItemData(item: WfrpMutationItem): Record<string, unknown> {
  const data = item.toObject();
  delete data["_id"];
  delete data["_key"];
  delete data["_stats"];
  delete data["folder"];
  delete data["ownership"];
  return data;
}

function createPrejudiceMutation(result: FoundryTableResult): ResolvedMutation {
  return {
    data: {
      effects: [],
      flags: {
        [MODULE_ID]: {
          patron: "khorne",
          sourceDocument: "The Mutant's Handbook",
        },
      },
      img: result.img ?? "systems/wfrp4e/icons/blank.png",
      name: result.name,
      system: {
        description: { value: result.description },
        gmdescription: { value: "" },
        modifier: { value: "" },
        modifiesSkills: { value: false },
        mutationType: { value: "mental" },
        source: { value: "The Mutant's Handbook" },
      },
      type: "mutation",
    },
    name: result.name,
    nature: "mental",
  };
}

export async function resolveMutationResult(
  result: FoundryTableResult,
  patron?: ChaosPatron,
): Promise<ResolvedMutation> {
  if (!result.documentUuid) {
    if (patron === "khorne" && result.name.trim().toLowerCase() === "prejudice") {
      return createPrejudiceMutation(result);
    }

    throw new Error(`The table result ${result.name} does not link to a mutation Item.`);
  }

  const item = await fromUuid(result.documentUuid);

  if (!isMutationItem(item)) {
    throw new Error(`The table result ${result.name} does not resolve to a mutation Item.`);
  }

  const nature = resolveMutationNature(item.system.mutationType.value);

  if (!nature) {
    throw new Error(`The mutation ${item.name} has no physical or mental classification.`);
  }

  const acquisition = (
    item.getFlag(MODULE_ID, "mutationAutomation") as MutationAutomationFlag | null
  )?.acquisition;
  return {
    ...(acquisition ? { acquisition } : {}),
    data: copyItemData(item),
    name: item.name,
    nature,
  };
}

export function getMutationAcquisitionBlock(
  actor: WfrpActor,
  mutation: ResolvedMutation,
): string | undefined {
  const activeMutations = (actor.itemTypes.mutation ?? []).filter(
    (item) => item.getFlag(MODULE_ID, POSSESSION_REMOVED_FLAG) !== true,
  );
  const existing = activeMutations.filter(
    (item) => item.name.trim().toLowerCase() === mutation.name.trim().toLowerCase(),
  ).length;
  const maximum = mutation.acquisition?.max;

  if (maximum !== undefined && existing >= maximum) {
    return `${mutation.name} has reached its acquisition maximum of ${maximum}.`;
  }

  const conflict = mutation.acquisition?.conflicts?.find((name) =>
    activeMutations.some((item) => item.name.trim().toLowerCase() === name.trim().toLowerCase()),
  );
  return conflict
    ? `${mutation.name} conflicts with the existing ${conflict} mutation.`
    : undefined;
}

export function getMutationCounts(actor: WfrpActor): MutationCounts {
  const isChosen = getChosenPatron(actor) !== undefined;
  const natures = (actor.itemTypes.mutation ?? [])
    .filter(
      (item) =>
        item.getFlag(MODULE_ID, POSSESSION_REMOVED_FLAG) !== true &&
        !(isChosen && item.name.trim().toLowerCase() === "possessed"),
    )
    .map((item) => item.system.mutationType.value);
  return countMutationNatures(natures);
}

export function getChosenPatron(actor: WfrpActor): ChosenPatron | undefined {
  const value = actor.getFlag(MODULE_ID, CHOSEN_PATRON_FLAG);
  return CHAOS_PATRONS.find((patron) => patron === value);
}

export function hasPossessedMutation(actor: WfrpActor): boolean {
  return (actor.itemTypes.mutation ?? []).some(
    (item) =>
      item.name.trim().toLowerCase() === "possessed" &&
      item.getFlag(MODULE_ID, POSSESSION_REMOVED_FLAG) !== true,
  );
}

export function hasMutationNamed(actor: WfrpActor, name: string): boolean {
  const normalizedName = name.trim().toLowerCase();
  return (actor.itemTypes.mutation ?? []).some(
    (item) =>
      item.name.trim().toLowerCase() === normalizedName &&
      item.getFlag(MODULE_ID, POSSESSION_REMOVED_FLAG) !== true,
  );
}

export function isHandbookChaosSpawn(actor: WfrpActor): boolean {
  return actor.getFlag(MODULE_ID, CHAOS_SPAWN_FLAG) === true;
}

export async function retirePossessedMutations(actor: WfrpActor): Promise<void> {
  const updates = (actor.itemTypes.mutation ?? [])
    .filter(
      (item) =>
        item.name.trim().toLowerCase() === "possessed" &&
        item.getFlag(MODULE_ID, POSSESSION_REMOVED_FLAG) !== true,
    )
    .map((item) => ({
      _id: item.id,
      [`flags.${MODULE_ID}.${POSSESSION_REMOVED_FLAG}`]: true,
    }));

  if (updates.length > 0) {
    const updatedItems = await actor.updateEmbeddedDocuments("Item", updates);

    if (updatedItems.length !== updates.length) {
      throw new Error(`Foundry prevented Possessed from being retired for ${actor.name}.`);
    }
  }
}
