import type { WfrpActor, WfrpMutationItem } from "../../../../types/foundry";
import type { MutationGrantDefinition } from "../../../../types/mutants-handbook";
import { MODULE_ID } from "../../../constants";
import {
  configureGrantData,
  getGrantOwnership,
  getLegacyGrantOwners,
  mutationGrantSignature,
  type MutationGrantOwner,
  type MutationGrantOwnership,
} from "./grant-data";
import { cleanOwnerReferences, type ExpectedGrant } from "./grant-reconciliation/owner-cleanup";
import {
  actorItems,
  findGrantCandidate,
  isActor,
  isFirstAcquisition,
  isItem,
  mutationAutomation,
  ownershipForCandidate,
  updateItem,
} from "./grant-reconciliation/helpers";
import {
  reconcileRankedSkillGrants,
  type RankedSkillGrantRequest,
} from "./skill-grant-reconciliation";

const actorQueues = new Map<string, Promise<void>>();

async function createGrant(
  actor: WfrpActor,
  source: WfrpMutationItem,
  grant: MutationGrantDefinition,
  signature: string,
  owner: MutationGrantOwner,
): Promise<string | undefined> {
  const data = configureGrantData(source.toObject(), grant);
  delete data["_id"];
  delete data["_key"];
  const flags =
    typeof data["flags"] === "object" && data["flags"] !== null
      ? (data["flags"] as Record<string, unknown>)
      : {};
  data["flags"] = flags;
  const moduleFlags =
    typeof flags[MODULE_ID] === "object" && flags[MODULE_ID] !== null
      ? (flags[MODULE_ID] as Record<string, unknown>)
      : {};
  flags[MODULE_ID] = moduleFlags;
  moduleFlags["mutationGrant"] = {
    managed: true,
    owners: [owner],
    signature,
    sourceUuid: grant.sourceUuid,
    version: 2,
  } satisfies MutationGrantOwnership;

  const created = await actor.createEmbeddedDocuments("Item", [data], {
    skipSpecialisationChoice: true,
  });
  return created[0]?.id;
}

async function reconcileGrant(
  actor: WfrpActor,
  mutation: WfrpMutationItem,
  grant: MutationGrantDefinition,
): Promise<ExpectedGrant> {
  const signature = mutationGrantSignature(grant);
  const source = await fromUuid(grant.sourceUuid);
  if (!isItem(source)) {
    ui.notifications.warn(
      `${mutation.name}: could not grant ${grant.configure?.name ?? grant.key}. Enable its source module and reconcile mutation automation.`,
    );
    return { signature };
  }

  const owner = { grantKey: grant.key, ownerId: mutation.id };
  const candidate = findGrantCandidate(actor, source, grant, signature, owner);

  if (!candidate) {
    const itemId = await createGrant(actor, source, grant, signature, owner);
    return itemId ? { itemId, signature } : { signature };
  }

  const ownership = ownershipForCandidate(candidate, grant, signature, owner);
  const moduleFlags = candidate.flags?.[MODULE_ID] ?? {};
  if (
    JSON.stringify(getGrantOwnership(candidate)) === JSON.stringify(ownership) &&
    !("mutationGrantManaged" in moduleFlags) &&
    !("mutationGrantOwners" in moduleFlags)
  ) {
    return { itemId: candidate.id, signature };
  }

  await updateItem(actor, candidate, {
    [`flags.${MODULE_ID}.mutationGrant`]: ownership,
    [`flags.${MODULE_ID}.-=mutationGrantManaged`]: null,
    [`flags.${MODULE_ID}.-=mutationGrantOwners`]: null,
  });
  return { itemId: candidate.id, signature };
}

async function reconcileMutation(actor: WfrpActor, mutation: WfrpMutationItem): Promise<void> {
  const definition = mutationAutomation(mutation);
  if (!definition) return;

  const grants = (definition.grants ?? []).filter(
    (grant) =>
      (grant.scope !== "first" || isFirstAcquisition(actor, mutation, definition.definitionId)) &&
      !(grant.type === "skill" && grant.stack === "rank"),
  );
  const expected = new Map<string, ExpectedGrant>();
  for (const grant of grants) {
    expected.set(grant.key, await reconcileGrant(actor, mutation, grant));
  }
  await cleanOwnerReferences(actor, mutation.id, expected);
}

export async function reconcileActorMutationAutomation(actor: WfrpActor): Promise<void> {
  const mutations = actorItems(actor).filter((item) => item.type === "mutation");
  const rankedSkills: RankedSkillGrantRequest[] = [];
  for (const mutation of mutations) {
    const definition = mutationAutomation(mutation);
    if (!definition) continue;
    for (const grant of definition.grants ?? []) {
      if (
        grant.type === "skill" &&
        grant.stack === "rank" &&
        (grant.scope !== "first" || isFirstAcquisition(actor, mutation, definition.definitionId))
      ) {
        rankedSkills.push({ grant, mutation });
      }
    }
  }
  await reconcileRankedSkillGrants(actor, rankedSkills);

  for (const mutation of mutations) {
    await reconcileMutation(actor, mutation);
  }

  const mutationIds = new Set(
    actorItems(actor)
      .filter((item) => item.type === "mutation" && mutationAutomation(item) !== undefined)
      .map((item) => item.id),
  );
  const orphanOwnerIds = new Set<string>();
  for (const item of actorItems(actor)) {
    for (const owner of getGrantOwnership(item)?.owners ?? []) {
      if (!mutationIds.has(owner.ownerId)) orphanOwnerIds.add(owner.ownerId);
    }
    for (const legacyOwnerId of getLegacyGrantOwners(item)) {
      if (!mutationIds.has(legacyOwnerId)) orphanOwnerIds.add(legacyOwnerId);
    }
  }
  for (const orphanOwnerId of orphanOwnerIds) {
    await cleanOwnerReferences(actor, orphanOwnerId, new Map());
  }
}

async function enqueueActorOperation(
  actorUuid: string,
  operation: () => Promise<void>,
): Promise<void> {
  const previous = actorQueues.get(actorUuid) ?? Promise.resolve();
  const current = previous.catch(() => undefined).then(operation);
  actorQueues.set(actorUuid, current);

  try {
    await current;
  } finally {
    if (actorQueues.get(actorUuid) === current) actorQueues.delete(actorUuid);
  }
}

export async function reconcileMutationAutomation(actorUuid: string): Promise<void> {
  const actor = await fromUuid(actorUuid);
  if (!isActor(actor)) {
    throw new Error(`Mutation automation could not resolve Actor ${actorUuid}.`);
  }
  await enqueueActorOperation(actorUuid, () => reconcileActorMutationAutomation(actor));
}

export async function removeMutationGrantOwner(actorUuid: string, ownerId: string): Promise<void> {
  const actor = await fromUuid(actorUuid);
  if (!isActor(actor)) {
    throw new Error(`Mutation automation could not resolve Actor ${actorUuid}.`);
  }
  await enqueueActorOperation(actorUuid, async () => {
    await cleanOwnerReferences(actor, ownerId, new Map());
    await reconcileActorMutationAutomation(actor);
  });
}
