import type { WfrpActor } from "../../../types/foundry";
import { HANDBOOK_TEST_OPTION } from "./constants";
import { isHandbookChaosSpawn, isWfrpActor } from "./documents";
import { postMutationMessage } from "./messages";
import { finalizeCorruptionTest } from "./test-resolution";
import { runFailedCorruptionCheck } from "./workflow";

const activeActors = new Set<string>();

export async function checkMutantsHandbookCorruption(actor: WfrpActor): Promise<void> {
  const corruption = actor.system.status.corruption;

  if (
    Number(corruption.value) <= Number(corruption.max) ||
    activeActors.has(actor.uuid) ||
    isHandbookChaosSpawn(actor)
  ) {
    return;
  }

  if (!game) {
    throw new Error("Foundry game global is unavailable during a corruption check.");
  }

  activeActors.add(actor.uuid);

  try {
    const endurance = game.i18n.localize("NAME.Endurance");
    const context = {
      fields: { difficulty: "challenging" },
      [HANDBOOK_TEST_OPTION]: true,
      skipTargets: true,
      title: game.i18n.format("DIALOG.MutateTitle", { test: endurance }),
    };
    const enduranceSkill = actor.has(endurance, "skill");
    const test = enduranceSkill
      ? await actor.setupSkill(enduranceSkill, context)
      : await actor.setupCharacteristic("t", context);

    if (!test) {
      return;
    }

    await test.roll();

    const passed = await finalizeCorruptionTest(actor, test);

    if (!passed) {
      await runFailedCorruptionCheck(actor);
    } else {
      await postMutationMessage(game.i18n.localize("CHAT.MutateSuccess"));
    }
  } finally {
    activeActors.delete(actor.uuid);
  }
}

export async function checkMutantsHandbookCorruptionByUuid(actorUuid: string): Promise<void> {
  const actor = await fromUuid(actorUuid);

  if (!isWfrpActor(actor)) {
    throw new Error(`${actorUuid} does not resolve to a WFRP4e character Actor.`);
  }

  await checkMutantsHandbookCorruption(actor);
}
